using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TreatyNegotiationsTests
{
    static readonly EntityId Own=TruceNegotiationTests.Own,Other=TruceNegotiationTests.Oda;
    static WorldSession Start()=>TruceNegotiationTests.Start();
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long at)=>TruceNegotiationTests.Advance(s,at);
    static long Arrival(WorldSession s,string message)=>s.DiagnosticSnapshot().Couriers!.Missions.Single(c=>s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==message)).ReadyAt;
    static void Open(WorldSession s,string id)=>Good(s.Open(s.PlayerControl,new(id),s.Revision));
    static void Offer(WorldSession s,TreatyClause clauses=TreatyClause.NonAggression|TreatyClause.Passage|TreatyClause.Supply|TreatyClause.Defense,int days=30)=>Good(s.NegotiateTreaty(new(new("request:treaty-offer/"+s.Revision),TreatyAction.Propose,Own,Other,Days:days,Clauses:clauses,NoticeDays:1),s.PlayerControl,s.Revision));
    static TreatyPaper Reply(WorldSession s)=>s.DiagnosticSnapshot().Treaties!.Papers.Last(p=>p.Input.Action==TreatyAction.Accept);
    static WorldSession Formed(bool open=true){var s=Start();Offer(s);var p=s.DiagnosticSnapshot().Treaties!.Papers.Single();At(s,Arrival(s,p.Message)+1);var reply=Reply(s);At(s,Arrival(s,reply.Message));if(open)Open(s,reply.Message);return s;}
    static EntityId Form(WorldSession s)=>s.DiagnosticSnapshot().Treaties!.Formations.Last().Acceptance;
    static TreatyOperationInput Operation(WorldSession s,TreatyOperation kind)=>new(new("request:treaty-op/"+s.Revision+"/"+kind),kind,Form(s),Own,Other,EffectiveAt:kind==TreatyOperation.Terminate?s.Seconds+86400:0,ReplyBy:kind is TreatyOperation.RequestDefense or TreatyOperation.RequestSupply?s.Seconds+3*86400:0,Amount:kind is TreatyOperation.RequestDefense or TreatyOperation.RequestSupply?20:0,Evidence:kind is TreatyOperation.RequestDefense or TreatyOperation.RequestSupply?"現地の不足を確認した":null);
    static TreatyOperationPaper Operate(WorldSession s,TreatyOperationInput i){Good(s.OperateTreaty(i,s.PlayerControl,s.Revision));return s.DiagnosticSnapshot().Treaties!.Operations.Last();}
    [Fact]public void PhysicalFormationAndPersonalOpeningAreSeparate(){var s=Formed(false);Assert.Single(s.DiagnosticSnapshot().Treaties!.Formations);Assert.Empty(TreatyNegotiations.Known(s.DiagnosticSnapshot(),s.PlayerControl));Assert.False(TreatyNegotiations.ClauseUsable(s.DiagnosticSnapshot(),s.PlayerControl,Form(s),TreatyClause.NonAggression));Open(s,Reply(s).Message);Assert.True(TreatyNegotiations.ClauseUsable(s.DiagnosticSnapshot(),s.PlayerControl,Form(s),TreatyClause.NonAggression));Assert.DoesNotContain(s.DiagnosticSnapshot().Treaties!.Papers,p=>p.Input.Action==TreatyAction.Confirm&&p.Author==s.PlayerControl);new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(TreatyClause.Passage)][InlineData(TreatyClause.Supply)][InlineData(TreatyClause.Defense)][InlineData(TreatyClause.NonAggression)]public void ClauseRightsRemainIndependent(TreatyClause clause){var s=Start();Offer(s,clause);var p=s.DiagnosticSnapshot().Treaties!.Papers.Single();At(s,Arrival(s,p.Message)+1);At(s,Arrival(s,Reply(s).Message));Open(s,Reply(s).Message);Assert.True(TreatyNegotiations.ClauseUsable(s.DiagnosticSnapshot(),s.PlayerControl,Form(s),clause));foreach(var missing in new[]{TreatyClause.NonAggression,TreatyClause.Passage,TreatyClause.Supply,TreatyClause.Defense}.Where(c=>c!=clause))Assert.False(TreatyNegotiations.ClauseUsable(s.DiagnosticSnapshot(),s.PlayerControl,Form(s),missing));Assert.Equal(clause==TreatyClause.NonAggression,TreatyNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Own,Other,s.Seconds,s.Revision));}
    [Fact]public void TerminationNeedsArrivalAndNoticeDateNotJustDispatch(){var s=Formed();var p=Operate(s,Operation(s,TreatyOperation.Terminate));Assert.Null(TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),Form(s)));At(s,Arrival(s,p.Message));Assert.Null(TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),Form(s)));At(s,p.Intent.EffectiveAt);Assert.Equal(p.Intent.EffectiveAt,TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),Form(s)));Assert.True(TreatyNegotiations.ClauseUsable(s.DiagnosticSnapshot(),s.PlayerControl,Form(s),TreatyClause.NonAggression));var ack=s.DiagnosticSnapshot().Treaties!.Operations.Single(p=>p.Kind==TreatyOperation.TerminationReceipt);At(s,Math.Max(s.Seconds,Arrival(s,ack.Message)));Open(s,ack.Message);Assert.False(TreatyNegotiations.ClauseUsable(s.DiagnosticSnapshot(),s.PlayerControl,Form(s),TreatyClause.NonAggression));new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(TreatyOperation.RequestDefense)][InlineData(TreatyOperation.RequestSupply)]public void AcknowledgedRequestDoesNotCreateArmyOrGoods(TreatyOperation kind){var s=Formed();var before=s.DiagnosticSnapshot();var p=Operate(s,Operation(s,kind));At(s,Arrival(s,p.Message)+1);var ack=s.DiagnosticSnapshot().Treaties!.Operations.Single(p=>p.Kind==TreatyOperation.Acknowledge);At(s,Arrival(s,ack.Message));Open(s,ack.Message);var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(w.Units));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Contains(TreatyNegotiations.OperationView(w),c=>c.Id==p.Input.Id&&c.Status.Contains("実行済みではない"));new WorldSession(w);}
    [Fact]public void LostTerminationDoesNotEndAndRetryNeedsOpenedFailure(){var s=Formed();var p=Operate(s,Operation(s,TreatyOperation.Terminate));s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,p.Message));At(s,Arrival(s,p.Message)+1);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Message));At(s,Arrival(s,f.Id));var retry=new TreatyOperationInput(new("request:treaty-op-retry"),TreatyOperation.Resend,Form(s),Own,Other,p.Input.Id);Assert.Equal(ResultCode.NotAvailable,s.OperateTreaty(retry,s.PlayerControl,s.Revision).Code);Open(s,f.Id);var copy=Operate(s,retry);Assert.Equal(p.Intent,copy.Intent);Assert.Equal(p.Authority,copy.Authority);At(s,Math.Max(copy.Intent.EffectiveAt,Arrival(s,copy.Message)));Assert.NotNull(TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),Form(s)));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void DuplicateStaleAndForeignActorCannotRepeatOperation(){var s=Formed();var i=Operation(s,TreatyOperation.RequestSupply);Assert.Equal(ResultCode.StateChanged,s.OperateTreaty(i,s.PlayerControl,s.Revision-1).Code);Assert.Equal(ResultCode.NotAvailable,s.OperateTreaty(i,TruceNegotiationTests.Head,s.Revision).Code);Operate(s,i);Assert.Equal(ResultCode.AlreadyAccepted,s.OperateTreaty(i,s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.OperateTreaty(i with{Amount=3},s.PlayerControl,s.Revision).Code);}
    [Fact]public void OriginalTruceWorldDoesNotAcquireAnEmptyTreatyExtension(){var s=Start();s.SetPaused(false);s.AdvanceTo(10,100000);Assert.Null(s.DiagnosticSnapshot().Treaties);}

    static void Confirm(WorldSession s){var p=Reply(s);Good(s.NegotiateTreaty(new(new("request:treaty-confirm/"+s.Revision),TreatyAction.Confirm,Own,Other,p.Input.Id),s.PlayerControl,s.Revision));var c=s.DiagnosticSnapshot().Treaties!.Papers.Last();At(s,Arrival(s,c.Message)+1);}
    [Theory][InlineData(0,1)][InlineData(16,1)][InlineData(1,0)][InlineData(1,8)][InlineData(1,91)]public void InvalidClausesAndNoticePeriodsAreRejected(int clauses,int days){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.NegotiateTreaty(new(new("request:invalid-treaty"),TreatyAction.Propose,Own,Other,Days:30,Clauses:(TreatyClause)clauses,NoticeDays:days),s.PlayerControl,s.Revision).Code);}
    [Fact]public void AcceptanceCannotChangeOfferedClauses(){var s=Start();Offer(s,TreatyClause.Supply,90);var offer=s.DiagnosticSnapshot().Treaties!.Papers.Single();At(s,Arrival(s,offer.Message)+1);var counter=s.DiagnosticSnapshot().Treaties!.Papers.Last();At(s,Arrival(s,counter.Message));Open(s,counter.Message);Assert.Equal(ResultCode.NotAvailable,s.NegotiateTreaty(new(new("request:treaty-tampered-reply"),TreatyAction.Accept,Own,Other,counter.Input.Id,Clauses:TreatyClause.Defense),s.PlayerControl,s.Revision).Code);}
    [Fact]public void CounterKeepsAllIndependentClausesAndNoticePeriod(){var s=Start();Offer(s,TreatyClause.Passage|TreatyClause.Supply,90);var offer=s.DiagnosticSnapshot().Treaties!.Papers.Single();At(s,Arrival(s,offer.Message)+1);var p=s.DiagnosticSnapshot().Treaties!.Papers.Last();Assert.Equal(TreatyAction.Counter,p.Input.Action);Assert.Equal(offer.Terms.Clauses,p.Terms.Clauses);Assert.Equal(offer.Terms.NoticeSeconds,p.Terms.NoticeSeconds);At(s,Arrival(s,p.Message));Open(s,p.Message);Good(s.NegotiateTreaty(new(new("request:treaty-counter-accept"),TreatyAction.Accept,Own,Other,p.Input.Id),s.PlayerControl,s.Revision));var reply=Reply(s);At(s,Arrival(s,reply.Message)+1);Assert.Single(s.DiagnosticSnapshot().Treaties!.Formations);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void PlayerFormationConfirmationIsExplicit(){var s=Formed();Assert.DoesNotContain(s.DiagnosticSnapshot().Treaties!.Papers,p=>p.Input.Action==TreatyAction.Confirm&&p.Author==s.PlayerControl);Confirm(s);Assert.Single(s.DiagnosticSnapshot().Treaties!.Papers,p=>p.Input.Action==TreatyAction.Confirm&&p.Author==s.PlayerControl);Assert.True(TreatyNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Other,Own,s.Seconds,s.Revision));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ForgedOperationCannotLoad(int n){var s=Formed();var p=Operate(s,Operation(s,TreatyOperation.Terminate));var w=s.DiagnosticSnapshot();w.Treaties!.Operations[0]=n switch{0=>p with{Address=new("site:unknown")},1=>p with{Intent=p.Intent with{EffectiveAt=0}},2=>p with{Author=s.DiagnosticSnapshot().Treaties!.Papers.Last().Author},3=>p with{Authority=p.Authority! with{Owner=Other}},_=>p with{ObservedAt=0}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData("Operations")][InlineData("OperationArrivals")][InlineData("OperationOpenings")][InlineData("FailureOpenings")][InlineData("Formations")]public void RequiredTreatyFieldsCannotBeOmitted(string field){var s=Formed();var node=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(s.DiagnosticSnapshot()))!;node["Treaties"]!.AsObject().Remove(field);Assert.Throws<InvalidDataException>(()=>ContractJson.Read<ContractWorld>(System.Text.Encoding.UTF8.GetBytes(node.ToJsonString())));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(8)][InlineData(9)][InlineData(10)][InlineData(11)]public void ActualGenerationRecoveryKeepsTreatyHistoryAndEqualFuture(int phase){var s=phase<2?Start():Formed(phase>=3);if(phase==1)Offer(s);if(phase>=4)Confirm(s);TreatyOperationPaper? request=null;if(phase>=5){request=Operate(s,Operation(s,TreatyOperation.RequestSupply));if(phase>=6)At(s,Arrival(s,request.Message)+1);if(phase>=7){var ack=s.DiagnosticSnapshot().Treaties!.Operations.Last(p=>p.Kind==TreatyOperation.Acknowledge);At(s,Arrival(s,ack.Message));Open(s,ack.Message);}}if(phase>=8){var end=Operate(s,Operation(s,TreatyOperation.Terminate));if(phase==11){s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,end.Message));At(s,Arrival(s,end.Message)+1);var failure=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==end.Message));At(s,Arrival(s,failure.Id));Open(s,failure.Id);Operate(s,new(new("request:treaty-save-retry"),TreatyOperation.Resend,Form(s),Own,Other,end.Input.Id));}else if(phase>=9){At(s,Math.Max(end.Intent.EffectiveAt,Arrival(s,end.Message)+1));if(phase>=10){var ack=s.DiagnosticSnapshot().Treaties!.Operations.Single(p=>p.Kind==TreatyOperation.TerminationReceipt);At(s,Math.Max(s.Seconds,Arrival(s,ack.Message)));Open(s,ack.Message);}}}Save(s,phase);}
    static void Save(WorldSession s,int phase){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"treaty-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"treaty",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("treaty"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"treaty-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"treaty-"+phase+".restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
    static string Fail(WorldSession s,TreatyOperationPaper p){s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,p.Message));At(s,Arrival(s,p.Message)+1);var failure=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Message));At(s,Arrival(s,failure.Id));Open(s,failure.Id);return failure.Id;}
    static TreatyOperationPaper Retry(WorldSession s,TreatyOperationPaper p)=>Operate(s,new(new("request:treaty-copy/"+s.Revision),TreatyOperation.Resend,Form(s),Own,Other,p.Input.Id));
    [Theory][InlineData(false)][InlineData(true)]public void RecoveredNoticeAndCopyProduceOneLogicalReceipt(bool originalFirst){var s=Formed();var p=Operate(s,Operation(s,TreatyOperation.Terminate));Fail(s,p);var copy=Retry(s,p);if(!originalFirst)At(s,Arrival(s,copy.Message)+1);s.DiagnosticRecoverLocalCourier(p.Message,1);At(s,s.Seconds+1);if(originalFirst)At(s,Arrival(s,copy.Message)+1);Assert.Single(s.DiagnosticSnapshot().Treaties!.Operations,p=>p.Kind==TreatyOperation.TerminationReceipt);At(s,p.Intent.EffectiveAt);Assert.Equal(p.Intent.EffectiveAt,TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),Form(s)));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void NoticeRetriesStopAfterThreeCopies(){var s=Formed();var p=Operate(s,Operation(s,TreatyOperation.Terminate));for(int n=0;n<3;n++){Fail(s,p);if(n<2)p=Retry(s,p);}Assert.False(TreatyNegotiations.CanOperate(s.DiagnosticSnapshot(),new(new("request:treaty-copy-four"),TreatyOperation.Resend,Form(s),Own,Other,p.Input.Id),s.PlayerControl));Assert.Equal(3,s.DiagnosticSnapshot().Treaties!.Operations.Count(p=>p.Kind==TreatyOperation.Terminate));}
    [Fact]public void TerminatingOneOriginalDoesNotEndAnotherTreaty(){var s=Formed();var old=Form(s);Offer(s,TreatyClause.Passage);var proposal=s.DiagnosticSnapshot().Treaties!.Papers.Last();At(s,Arrival(s,proposal.Message)+1);At(s,Arrival(s,Reply(s).Message));Open(s,Reply(s).Message);var current=s.DiagnosticSnapshot().Treaties!.Formations.Last().Acceptance;var notice=Operate(s,Operation(s,TreatyOperation.Terminate) with{Acceptance=old});At(s,Math.Max(notice.Intent.EffectiveAt,Arrival(s,notice.Message)+1));Assert.NotNull(TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),old));Assert.Null(TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),current));Assert.True(TreatyNegotiations.ClauseUsable(s.DiagnosticSnapshot(),s.PlayerControl,current,TreatyClause.Passage));}
    [Fact]public void ACharacterWithoutTheActualOfficeCannotSignForTheHouse(){var s=Formed();Assert.Null(FactionStances.ResolveAuthority(s.DiagnosticSnapshot(),s.PlayerControl,Other,s.Seconds,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.OperateTreaty(Operation(s,TreatyOperation.Terminate) with{Owner=Other,Target=Own},s.PlayerControl,s.Revision).Code);}
    [Fact]public void ADelayedCopyEndsOnlyWhenActuallyDeliveredAfterTheNoticeDate(){var s=Formed();var p=Operate(s,Operation(s,TreatyOperation.Terminate));Fail(s,p);At(s,p.Intent.EffectiveAt+1);Assert.Null(TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),Form(s)));var copy=Retry(s,p);At(s,Arrival(s,copy.Message)+1);Assert.Equal(Arrival(s,copy.Message),TreatyNegotiations.TruthEnd(s.DiagnosticSnapshot(),Form(s)));}

    [Theory][InlineData(TreatyOperation.RequestSupply)][InlineData(TreatyOperation.RequestDefense)]public void ARequestCannotBorrowAMissingClause(TreatyOperation kind){var s=Start();Offer(s,TreatyClause.NonAggression);var p=s.DiagnosticSnapshot().Treaties!.Papers.Single();At(s,Arrival(s,p.Message)+1);At(s,Arrival(s,Reply(s).Message));Open(s,Reply(s).Message);Assert.False(TreatyNegotiations.CanOperate(s.DiagnosticSnapshot(),Operation(s,kind),s.PlayerControl));}
}
